style.css:
@-moz-document domain("character.ai") {
/* Sobrescribir variables globales para fondo */
  html.dark {
    --G950: rgba(68, 90, 105, 0.8) !important; /* sidebar general */
    --G800: rgba(50, 65, 80, 0.75) !important; /* translúcido más claro */
    --G850: rgba(35, 45, 55, 0.8) !important; /* azul grisáceo súper oscuro */
  }

  /* Fondo general */
  body {
    background-image: url("https://cl.pinterest.com/pin/4151824652378136/") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    color: #d2dbeb !important;
  }
  body::before {
    content:"";
    position:fixed;
    inset:0;
    background-color:rgba(0,0,0,0.55) !important;
    z-index:-1;
  }

  /* Chat y mensajes */
  .chat-message, .message, .chat-bubble {
    color:#d2dbeb !important;
    border-radius:12px !important;
    padding:10px !important;
  }

  /* Botones */
  button, .btn, .button, input[type="submit"], .c-button {
    background-color:#728fa2 !important;
    color:#d2dbeb !important;
    border-radius:6px !important;
  }

  /* Inputs */
  input, textarea {
    background-color:#445a69 !important;
    color:#d2dbeb !important;
    border:1px solid #728fa2 !important;
    border-radius:8px !important;
  }

  /* Tarjetas personajes */
  .cai-card, .character-card, .card, .recommendation-card, .ca-card {
    background-color:rgba(68, 90, 105, 0.8) !important;
    color:#d2dbeb !important;
    border-radius:12px !important;
    backdrop-filter:blur(3px) !important;
  }

  /* Sidebar y topbar */
  html.dark nav,
  html.dark header,
  html.dark aside,
  html.dark .sidebar,
  html.dark .side-nav,
  html.dark .side-navbar,
  html.dark nav[data-testid="side-nav"],
  html.dark .left-section {
    background-color: rgba(68, 90, 105, 0.8) !important;
    backdrop-filter: blur(4px) !important;
  }
  html.dark nav *,
  html.dark header *,
  html.dark aside *,
  html.dark .sidebar * {
    color: #2c3e50 !important;
    fill: #2c3e50 !important;
    stroke: #2c3e50 !important;
  }
}
